/bin/zsh -lc "python3 -c 'import json; from pathlib import Path; wanted={\"배포하다\",\"업로드하다\",\"시간 초과\",\"지원하다\",\"수 있다\",\"수 없다\",\"승인하다\",\"검토하다\",\"요청하다\",\"보류하다\",\"적용하다\",\"롤백하다\"};
def visit(x):
 if isinstance(x,dict):
  if x.get(\"lemma\") in wanted: print(json.dumps({k:v for k,v in x.items() if k in (\"lemma\",\"meaning\",\"sense\",\"argument_patterns\",\"usage_conditions\",\"constraints\",\"allowed_forms\",\"notes\")},ensure_ascii=False))
  else:
   for v in x.values(): visit(v)
 elif isinstance(x,list):
  for v in x: visit(v)
for name in (\"lexicon/core.json\",\"lexicon/domains/software.json\"): visit(json.loads(Path(name).read_text()))'"

